def wrapper(*args, **kwargs):
    result = f(*args, **kwargs)
    items = []
    if isinstance(result, list):
        items = result
    elif isinstance(result, dict):
        items = [result]
    for item in items:
        if theSpider is not None:
            theSpider.saveItem(item)
    return items
return wrapper

