def get_alignak_configuration(self, section=SECTION_CONFIGURATION,
                                  legacy_cfg=False, macros=False):
        config = configparser.ConfigParser()
        config.read(self.config_file)
        if section not in config:
            raise ValueError(f"Section {section} not found in the configuration file")
        variables = config[section]
        if legacy_cfg:
            return {k: v for k, v in variables.items() if not k.startswith('cfg')}
        if macros:
            return {k: v for k, v in variables.items() if k.startswith('cfg')}
        return variables

