def cache_installed():
    """
    Returns ``True`` if a cache backend is configured, and the
    cache middleware classes or subclasses thereof are present.
    This will be evaluated once per run, and then cached.
    """
    try:
        from django.core.cache import cache
        from django.conf import settings
        if cache and settings.MIDDLEWARE:
            for middleware in settings.MIDDLEWARE:
                if middleware.endswith('CacheMiddleware') or middleware.endswith('UpdateCacheMiddleware'):
                    return True
    except ImportError:
        pass

    return False

