def get_arg_descriptions_from_docstring(cls, obj):
    docstring = inspect.getdoc(obj)
    param_regex = r":param (?P<arg_name>[a-zA-Z0-9_]+): (?P<arg_description>.*)"
    param_matches = re.findall(param_regex, docstring)
    param_descriptions = {match[0]: match[1] for match in param_matches}
    return param_descriptions

