def keyPressEvent(self, evt):
        """This handles Ctrl+PageUp, Ctrl+PageDown, Ctrl+Tab, Ctrl+Shift+Tab"""
        if evt.key() == Qt.Key_PageUp and evt.modifiers() & Qt.ControlModifier:
            self.pageUp()
        elif evt.key() == Qt.Key_PageDown and evt.modifiers() & Qt.ControlModifier:
            self.pageDown()
        elif evt.key() == Qt.Key_Tab and evt.modifiers() & Qt.ControlModifier:
            if evt.modifiers() & Qt.ShiftModifier:
                self.prevTab()
            else:
                self.nextTab()

