def bbox_horz_aligned(box1, box2):
    """
    Returns true if the vertical center point of either span is within the
    vertical range of the other
    """
    def center(box):
        return (box[1] + box[3]) / 2

    def in_range(box1, box2):
        return box1[1] <= box2[1] <= box1[3] or box2[1] <= box1[1] <= box2[3]

    return in_range(box1, box2) or in_range(box2, box1) or center(box1) == center(box2)

