blend_ratio = np.tile(blend_ratio, (img1.shape[1], 1)).T

img1_blend = img1[:-overlap, :] * (1 - blend_ratio) + background[:-overlap, :] * blend_ratio
img2_blend = img2[overlap:, :] * blend_ratio + background[overlap:, :] * (1 - blend_ratio)

return np.vstack((img1_blend, img2_blend))

