def linearBlend(img1, img2, overlap, backgroundColor=None):
    """
    Stitch 2 images vertically together.
    Smooth the overlap area of both images with a linear fade from img1 to img2

    @param img1: numpy.2dArray
    @param img2: numpy.2dArray of the same shape[1,2] as img1
    @param overlap: number of pixels both images overlap
    @returns: stitched-image
    """
    if backgroundColor is not None:
        background = np.full(img1.shape, backgroundColor)
    else:
        background = np.zeros(img1.shape)

    blend_ratio = np.linspace(0, 1, overlap)
    blend_ratio = np.tile(blend_ratio, (img1.shape[1], 1)).T

    img1_blend = img1[:-overlap, :] * (1 - blend_ratio) + background[:-overlap, :] * blend_ratio
    img2_blend = img2[overlap:, :] * blend_ratio + background[overlap:, :] * (1 - blend_ratio)

    return np.vstack((img1_blend, img2_blend))

